BEGIN; CREATE TEMP TABLE measured ("id" uuid DEFAULT uuidv7() NOT NULL,"access_token_jti_blake3" character varying(64) NOT NULL,"client_id" uuid NOT NULL,"revoked_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,"expires_at" timestamp with time zone NOT NULL,"tenant_id" uuid DEFAULT '00000000-0000-0000-0000-000000000001'::uuid NOT NULL);CREATE UNIQUE INDEX measured_index_0 ON measured USING btree (id);CREATE INDEX measured_index_1 ON measured USING btree (expires_at);CREATE INDEX measured_index_2 ON measured USING btree (tenant_id);CREATE UNIQUE INDEX measured_index_3 ON measured USING btree (tenant_id, access_token_jti_blake3);INSERT INTO measured(tenant_id,client_id,access_token_jti_blake3,revoked_at,expires_at) SELECT '00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000002',md5(i::text)||md5('jti-'||i::text),'2026-10-01T00:00:00Z','2026-11-10T00:00:00Z' FROM generate_series(1,10000) n(i); SELECT json_build_object('rows',count(*),'avg_tuple_bytes',avg(pg_column_size(d)),'heap_bytes',pg_table_size('measured'),'index_bytes',pg_indexes_size('measured'),'total_bytes',pg_total_relation_size('measured'),'dropped_slots',(SELECT count(*) FROM pg_attribute WHERE attrelid='measured'::regclass AND attnum>0 AND attisdropped)) FROM measured d; ROLLBACK;